"""Actual voxel geometry preview, with an explicit planar lithium counterelectrode."""
import json
from pathlib import Path


def particle_preview(structure,owners,destination,*,positive_nodes=6):
    root=Path(__file__).parent;js=(root/'nodewise.js').read_text().split('main().catch')[0]
    data={'shape':list(structure.labels.shape),'labels':structure.labels.ravel().tolist(),'spacing':list(structure.spacing_zyx_m),
        'phase_kinds':structure.phase_kinds,'owners':owners.ravel().tolist(),'metadata':structure.provenance}
    controls=''.join(f'<button class="node" data-node="{i}">正极 X{i+1}<small>32 × 32 × 32</small></button>' for i in range(positive_nodes))
    html='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MORQEX · 32³ 多颗粒正极 / Li</title><style>
*{box-sizing:border-box}body{margin:0;background:#f0f5fa;color:#18344d;font:14px/1.7 system-ui,"Noto Sans CJK SC",sans-serif}header{background:#12334e;color:white;padding:25px 5vw}h1{margin:0;font-size:25px}main{max-width:1300px;margin:20px auto;padding:0 20px}.card{background:white;border:1px solid #d6e3ec;border-radius:12px;padding:20px;margin:15px 0}.flow{display:flex;gap:8px;align-items:stretch}.metal{background:linear-gradient(110deg,#8395a6,#e5edf3,#879aab);border-radius:5px;padding:12px 18px;display:flex;align-items:center}.sep{background:#ecd6a2;width:10px;border-radius:4px}button,select{font:inherit;padding:6px;border:1px solid #b8ccdb;border-radius:6px;background:#f5faff;color:#234b67;cursor:pointer}button small{display:block;font-size:10px}button.active{background:#21677e;color:white}.node{flex:1}.grid{display:grid;grid-template-columns:3fr 1fr;gap:16px}#volume{width:100%;height:550px;display:block;background:radial-gradient(ellipse,#f6fbff,#e2edf5);border-radius:10px;touch-action:none}#slice{width:100%;height:280px;display:block}.controls{display:flex;gap:20px;flex-wrap:wrap}input{accent-color:#228b99}input[type=range]{width:100%}h2{font-size:18px;margin:0 0 10px}.metric{font-size:26px;color:#21677e}small{color:#647e92}p{margin:6px 0}pre{font:12px monospace;white-space:pre-wrap;word-break:break-all}.note{background:#edf7f6;color:#23585a;padding:10px;border-radius:6px}@media(max-width:800px){.grid{grid-template-columns:1fr}.flow{flex-wrap:wrap}#volume{height:420px}}
</style><header><h1>32³ 多颗粒正极 · 平面锂金属负极</h1><div>6 个正极厚度节点 · 真实体素几何 · CBD 导电粘结网络与电解液孔隙</div></header><main><div class="card"><div class="flow"><div class="metal">Li 金属<br>平面边界</div><div class="sep"></div>__CONTROLS__</div><p id="mapping"></p><small>此页展示实际生成的 32³ 几何。当前共享模式使用同一个不可变模板；后续每个节点的电化学和力学状态独立演化。</small></div><div class="grid"><div class="card"><h2 id="title">正极节点 1</h2><div class="controls"><label>显示 <select id="phase"><option value="active">全部活性颗粒</option><option value="cbd">CBD 碳胶网络</option><option value="solid">活性颗粒 + CBD</option><option value="pore">孔隙</option></select></label><label>着色 <select id="color"><option value="particle">颗粒编号</option><option value="phase">材料相</option></select></label></div><canvas id="volume"></canvas><label>沿 X 厚度剖开 <span id="cutText"></span><input id="cut" type="range" min="1" max="32" value="32"></label><small>拖动旋转。每一个显示的小方块都对应一个实际求解体素，未进行几何放大插值。</small></div><div class="card"><h2>实际几何统计</h2><div class="metric" id="count"></div><p id="fractions"></p><p id="physical"></p><canvas id="slice"></canvas><small>同一结构的 Z–Y 截面。</small><p class="note">几何预览不包含伪造的充放电或应力结果。32³ 耦合计算通过检查后，其演化场将在独立的计算报告中显示。</p><details><summary>来源与粒径参数</summary><pre id="provenance"></pre></details></div></div></main><script>__DATA__</script><script>__BASE_JS__</script><script>
let chosen=0;const n={g:PACK};
function drawPack(){let v=new Float64Array(PACK.labels.length);for(let i=0;i<v.length;i++)v[i]=$('color').value==='particle'?(PACK.owners[i]||0):PACK.labels[i];let hi=$('color').value==='particle'?PACK.metadata.particle_count:2;render3(n,v,0,hi);renderSlice(n,v,0,hi);$('cutText').textContent=$('cut').value+'/32';$('title').textContent='正极节点 '+(chosen+1)+' · 32 × 32 × 32';$('mapping').textContent='Li 平面负极 → 隔膜 → 正极 X1…X6；每个正极节点 32,768 个体素，6 个节点对应 196,608 个体素位置。'}
document.querySelectorAll('.node').forEach(b=>b.onclick=()=>{chosen=+b.dataset.node;document.querySelectorAll('.node').forEach(x=>x.classList.toggle('active',x===b));drawPack()});document.querySelector('.node').classList.add('active');for(let id of ['phase','color','cut'])$(id).oninput=drawPack;$('volume').onpointerdown=e=>{drag=[e.clientX,e.clientY];$('volume').setPointerCapture(e.pointerId)};$('volume').onpointermove=e=>{if(drag){yaw+=(e.clientX-drag[0])*.01;pitch=clamp(pitch+(e.clientY-drag[1])*.006,.15,1.3);drag=[e.clientX,e.clientY];drawPack()}};$('volume').onpointerup=()=>drag=null;window.onresize=drawPack;$('count').textContent=PACK.metadata.particle_count+' 个近球形颗粒';$('fractions').textContent='活性材料 '+(100*PACK.metadata.phase_fractions['1']).toFixed(2)+'% · CBD '+(100*PACK.metadata.phase_fractions['2']).toFixed(2)+'% · 孔隙 '+(100*PACK.metadata.phase_fractions['0']).toFixed(2)+'%';$('physical').textContent='实际尺寸 '+PACK.shape.map((n,i)=>(n*PACK.spacing[i]*1e6).toFixed(2)).join(' × ')+' μm；颗粒间最小连续几何间隙 '+PACK.metadata.minimum_surface_gap_voxels.toFixed(3)+' 体素。';$('provenance').textContent=JSON.stringify(PACK.metadata,null,2);drawPack();window.MORQEX_PACK_READY=true;
</script></html>'''
    html=html.replace('__CONTROLS__',controls).replace('__DATA__','const PACK='+json.dumps(data,separators=(',',':'))+';').replace('__BASE_JS__',js)
    import os
    font=Path(os.environ.get('MORQEX_WORKSPACE',str(Path(destination).parent.parent)))/'data/report_font'
    if (font/'NotoSansCJKsc-Regular.otf').exists():
        from .report_font import embed_font
        html=embed_font(html,font/'NotoSansCJKsc-Regular.otf',(font/'LICENSE').read_text())
    destination=Path(destination);destination.parent.mkdir(parents=True,exist_ok=True);destination.write_text(html)
    return destination
